-- Route the audited public-registration profile correction through the one canonical device dispatcher.
do $route$ declare o oid:='platform.execute_device_operation(uuid,uuid,bytea,text,text,jsonb)'::regprocedure;d text;n text;a text:=E'    when \'decide_public_registration_family_request\' then';i text:=E'    when \'update_public_registration_member_profile\' then\n      perform platform_private.require_exact_jsonb_keys(p_args,array[\'p_operation_id\',\'p_request_id\',\'p_expected_revision\',\'p_member_key\',\'p_governorate\',\'p_church\',\'p_city_or_village\']);\n      return reservations_private.update_public_registration_member_profile(v_session.device_id,(p_args->>\'p_operation_id\')::uuid,(p_args->>\'p_request_id\')::uuid,(p_args->>\'p_expected_revision\')::bigint,(p_args->>\'p_member_key\')::uuid,p_args->>\'p_governorate\',p_args->>\'p_church\',p_args->>\'p_city_or_village\');\n    when \'decide_public_registration_family_request\' then';begin select pg_get_functiondef(o)into d;if position('update_public_registration_member_profile' in d)>0 then raise exception 'PUBLIC_REGISTRATION_PROFILE_CORRECTION_DISPATCH_ALREADY_PRESENT';end if;if position(a in d)=0 then raise exception 'PUBLIC_REGISTRATION_PROFILE_CORRECTION_DISPATCH_ANCHOR_MISMATCH';end if;n:=replace(d,a,i);execute n;end $route$;
